let candidatos = [];
let totalCandidatos = 0;

try {
  // El AI Agent devuelve el resultado en la propiedad "output" como string JSON
  let output = item.output || '';

  // Limpiar posibles caracteres markdown (```json, etc.)
  output = output.replace(/```json\s?/g, '').replace(/```\s?/g, '').trim();

  // Parsear el JSON
  const parsed = JSON.parse(output);

  // Extraer candidatos_filtrados (el AI Agent usa este nombre)
  candidatos = parsed.candidatos_filtrados || [];
  totalCandidatos = parsed.total_encontrados || candidatos.length;

} catch (error) {
  console.error('Error parseando output del AI Agent:', error);
  console.log('Output recibido:', item.output);

  // Si falla el parseo, intentar buscar en otras propiedades
  if (item.analisis && item.analisis.candidatos) {
    candidatos = item.analisis.candidatos;
  }
  totalCandidatos = candidatos.length;
}

// Asegurar que candidatos sea un array
if (!Array.isArray(candidatos)) {
  candidatos = [];
  totalCandidatos = 0;
}

// Retornar para el siguiente nodo
