// Obtener todos los candidatos
const items = $input.all();


// Separar candidatos en dos grupos
const sinLinkedIn = [];
const conLinkedIn = [];

for (const item of items) {
  const data = item.json;

  if (data.urlLinkedin && data.urlLinkedin !== null) {
    // Candidatos CON LinkedIn
    conLinkedIn.push(item);
  } else {
    // Candidatos SIN LinkedIn (los que tienen correo)
    sinLinkedIn.push(item);
  }
}

// Construir el resultado final
const resultado = [];

// 1. Agregar TODOS los candidatos sin LinkedIn primero
resultado.push(...sinLinkedIn);

// 2. Calcular cuántos candidatos faltan para llegar a 10
const faltantes = 10 - resultado.length;

// 3. Agregar candidatos con LinkedIn hasta completar 10
if (faltantes > 0) {
  const candidatosLinkedIn = conLinkedIn.slice(0, faltantes);
  resultado.push(...candidatosLinkedIn);
}


// Retornar los 10 candidatos (o menos si no hay suficientes)
return resultado;

