    let linkedinLink = item.json["urlLinkedin "] || null; // Nota: el campo tiene espacio al final

    // Si NO tiene email pero SÍ tiene LinkedIn, usar LinkedIn en ambos campos
    if (!email && linkedinLink) {
        email = linkedinLink;
    }

    // Manejo de salaryExpectation (debe ser número o 0)
